--- ADPDU (IEEE 1722.1-2021 6.2.1)
function M.add_adp(tree, tvb, off)
    tree:add(M.f.atdecc_adp_subtype, tvb(off + 0, 1))
    tree:add(M.f.atdecc_adp_message_type, tvb(off + 1, 1))
    tree:add(M.f.atdecc_adp_valid_time, tvb(off + 2, 2))
    tree:add(M.f.atdecc_adp_control_data_length, tvb(off + 2, 2))
    tree:add(M.f.atdecc_adp_entity_id, tvb(off + 4, 8))
    tree:add(M.f.atdecc_adp_entity_model_id, tvb(off + 12, 8))
    tree:add(M.f.atdecc_adp_entity_cap_efu_mode, tvb(off + 20, 4))
    tree:add(M.f.atdecc_adp_entity_cap_address_access_supported, tvb(off + 20, 4))
    tree:add(M.f.atdecc_adp_entity_cap_gateway_entity, tvb(off + 20, 4))
    tree:add(M.f.atdecc_adp_entity_cap_aem_supported, tvb(off + 20, 4))
    tree:add(M.f.atdecc_adp_entity_cap_legacy_avc, tvb(off + 20, 4))
    tree:add(M.f.atdecc_adp_entity_cap_association_id_supported, tvb(off + 20, 4))
    tree:add(M.f.atdecc_adp_entity_cap_association_id_valid, tvb(off + 20, 4))
    tree:add(M.f.atdecc_adp_entity_cap_vendor_unique_supported, tvb(off + 20, 4))
    tree:add(M.f.atdecc_adp_entity_cap_class_a_supported, tvb(off + 20, 4))
    tree:add(M.f.atdecc_adp_entity_cap_class_b_supported, tvb(off + 20, 4))
    tree:add(M.f.atdecc_adp_entity_cap_gptp_supported, tvb(off + 20, 4))
    tree:add(M.f.atdecc_adp_entity_cap_aem_authentication_supported, tvb(off + 20, 4))
    tree:add(M.f.atdecc_adp_entity_cap_aem_authentication_required, tvb(off + 20, 4))
    tree:add(M.f.atdecc_adp_entity_cap_aem_persistent_acquire_supported, tvb(off + 20, 4))
    tree:add(M.f.atdecc_adp_entity_cap_aem_identify_control_index_valid, tvb(off + 20, 4))
    tree:add(M.f.atdecc_adp_entity_cap_aem_interface_index_valid, tvb(off + 20, 4))
    tree:add(M.f.atdecc_adp_entity_cap_general_controller_ignore, tvb(off + 20, 4))
    tree:add(M.f.atdecc_adp_entity_cap_entity_not_ready, tvb(off + 20, 4))
    tree:add(M.f.atdecc_adp_entity_cap_acmp_acquire_with_aem, tvb(off + 20, 4))
    tree:add(M.f.atdecc_adp_entity_cap_acmp_authenticate_with_aem, tvb(off + 20, 4))
    tree:add(M.f.atdecc_adp_entity_cap_supports_udpv4_atdecc, tvb(off + 20, 4))
    tree:add(M.f.atdecc_adp_entity_cap_supports_udpv4_streaming, tvb(off + 20, 4))
    tree:add(M.f.atdecc_adp_entity_cap_supports_udpv6_atdecc, tvb(off + 20, 4))
    tree:add(M.f.atdecc_adp_entity_cap_supports_udpv6_streaming, tvb(off + 20, 4))
    tree:add(M.f.atdecc_adp_entity_cap_multiple_ptp_instances, tvb(off + 20, 4))
    tree:add(M.f.atdecc_adp_entity_cap_aem_configuration_index_valid, tvb(off + 20, 4))
    tree:add(M.f.atdecc_adp_talker_stream_sources, tvb(off + 24, 2))
    tree:add(M.f.atdecc_adp_talker_cap_implemented, tvb(off + 26, 2))
    tree:add(M.f.atdecc_adp_talker_cap_other_source, tvb(off + 26, 2))
    tree:add(M.f.atdecc_adp_talker_cap_control_source, tvb(off + 26, 2))
    tree:add(M.f.atdecc_adp_talker_cap_media_clock_source, tvb(off + 26, 2))
    tree:add(M.f.atdecc_adp_talker_cap_smpte_source, tvb(off + 26, 2))
    tree:add(M.f.atdecc_adp_talker_cap_midi_source, tvb(off + 26, 2))
    tree:add(M.f.atdecc_adp_talker_cap_audio_source, tvb(off + 26, 2))
    tree:add(M.f.atdecc_adp_talker_cap_video_source, tvb(off + 26, 2))
    tree:add(M.f.atdecc_adp_listener_stream_sinks, tvb(off + 28, 2))
    tree:add(M.f.atdecc_adp_listener_cap_implemented, tvb(off + 30, 2))
    tree:add(M.f.atdecc_adp_listener_cap_other_sink, tvb(off + 30, 2))
    tree:add(M.f.atdecc_adp_listener_cap_control_sink, tvb(off + 30, 2))
    tree:add(M.f.atdecc_adp_listener_cap_media_clock_sink, tvb(off + 30, 2))
    tree:add(M.f.atdecc_adp_listener_cap_smpte_sink, tvb(off + 30, 2))
    tree:add(M.f.atdecc_adp_listener_cap_midi_sink, tvb(off + 30, 2))
    tree:add(M.f.atdecc_adp_listener_cap_audio_sink, tvb(off + 30, 2))
    tree:add(M.f.atdecc_adp_listener_cap_video_sink, tvb(off + 30, 2))
    tree:add(M.f.atdecc_adp_controller_cap_implemented, tvb(off + 32, 4))
    tree:add(M.f.atdecc_adp_available_index, tvb(off + 36, 4))
    tree:add(M.f.atdecc_adp_gptp_grandmaster_id, tvb(off + 40, 8))
    tree:add(M.f.atdecc_adp_gptp_domain_number, tvb(off + 48, 1))
    tree:add(M.f.atdecc_adp_reserved0, tvb(off + 49, 1))
    tree:add(M.f.atdecc_adp_current_configuration_index, tvb(off + 50, 2))
    tree:add(M.f.atdecc_adp_identify_control_index, tvb(off + 52, 2))
    tree:add(M.f.atdecc_adp_interface_index, tvb(off + 54, 2))
    tree:add(M.f.atdecc_adp_association_id, tvb(off + 56, 8))
    for i = 0, 3 do
        tree:add(M.f.atdecc_adp_reserved1, tvb(off + 64 + (i * 1), 1))
    end
end

--- ACMPDU (IEEE 1722.1-2021 8.2.1)
function M.add_acmp(tree, tvb, off)
    tree:add(M.f.atdecc_acmp_subtype, tvb(off + 0, 1))
    tree:add(M.f.atdecc_acmp_message_type, tvb(off + 1, 1))
    tree:add(M.f.atdecc_acmp_status, tvb(off + 2, 2))
    tree:add(M.f.atdecc_acmp_control_data_length, tvb(off + 2, 2))
    tree:add(M.f.atdecc_acmp_stream_id, tvb(off + 4, 8))
    tree:add(M.f.atdecc_acmp_controller_entity_id, tvb(off + 12, 8))
    tree:add(M.f.atdecc_acmp_talker_entity_id, tvb(off + 20, 8))
    tree:add(M.f.atdecc_acmp_listener_entity_id, tvb(off + 28, 8))
    tree:add(M.f.atdecc_acmp_talker_unique_id, tvb(off + 36, 2))
    tree:add(M.f.atdecc_acmp_listener_unique_id, tvb(off + 38, 2))
    tree:add(M.f.atdecc_acmp_stream_dest_mac, tvb(off + 40, 6))
